		System.arraycopy(this.byteArray,0,newByteArray,0,this.length);
		this.byteArray=newByteArray;
	}
	System.arraycopy(byteArrayValue,byteOffset,this.byteArray,this.length,byteLength);
	this.length+=byteLength;
	return this;
}

